interface CachedVersions {
  cachedVersions: string[]
  nonCachedVersions: string[]
  cachedAt?: string
  distTags: Record<string, string>
}

export async function cacheView (opts: { cacheDir: string, storeDir: string, registry?: string }, packageName: string): Promise<string> {
  const prefix = opts.registry ? `${getRegistryName(opts.registry)}` : '*'
  const metaFilePaths = (await fastGlob(`${prefix}/${packageName}.json`, {
    cwd: opts.cacheDir,
  })).sort()
  const metaFilesByPath: Record<string, CachedVersions> = {}
  for (const filePath of metaFilePaths) {
    const metaObject = JSON.parse(fs.readFileSync(path.join(opts.cacheDir, filePath), 'utf8')) as PackageMeta
    const cachedVersions: string[] = []
    const nonCachedVersions: string[] = []
    for (const [version, manifest] of Object.entries(metaObject.versions)) {
      if (!manifest.dist.integrity) continue
      const indexFilePath = getIndexFilePathInCafs(opts.storeDir, manifest.dist.integrity, `${manifest.name}@${manifest.version}`)
      if (fs.existsSync(indexFilePath)) {
        cachedVersions.push(version)
      } else {
        nonCachedVersions.push(version)
      }
    }
    let registryName = filePath
    while (path.dirname(registryName) !== '.') {
      registryName = path.dirname(registryName)
    }
    metaFilesByPath[registryName.replaceAll('+', ':')] = {
      cachedVersions,
      nonCachedVersions,
      cachedAt: metaObject.cachedAt ? new Date(metaObject.cachedAt).toString() : undefined,
      distTags: metaObject['dist-tags'],
    }
  }
  return JSON.stringify(metaFilesByPath, null, 2)
}
import path from 'path'
import { type DependencyManifest, type PackageBin } from '@pnpm/types'
import fastGlob from 'fast-glob'
import isSubdir from 'is-subdir'

export interface Command {
  name: string
  path: string
}

export async function getBinsFromPackageManifest (manifest: DependencyManifest, pkgPath: string): Promise<Command[]> {
  if (manifest.bin) {
    return commandsFromBin(manifest.bin, manifest.name, pkgPath)
  }
  if (manifest.directories?.bin) {
    const binDir = path.join(pkgPath, manifest.directories.bin)
    // Validate: directories.bin must be within the package root
    if (!isSubdir(pkgPath, binDir)) {
      return []
    }
    const files = await findFiles(binDir)
    return files.map((file) => ({
      name: path.basename(file),
      path: path.join(binDir, file),
    }))
  }
  return []
}

async function findFiles (dir: string): Promise<string[]> {
  try {
    return await fastGlob('**', {
      cwd: dir,
      onlyFiles: true,
      followSymbolicLinks: false,
      })
  } catch (err: any) { // eslint-disable-line
    if ((err as NodeJS.ErrnoException).code !== 'ENOENT') {
      throw err
    }
    return []
  }
}

function commandsFromBin (bin: PackageBin, pkgName: string, pkgPath: string): Command[] {
  const cmds: Command[] = []
  for (const [commandName, binRelativePath] of typeof bin === 'string' ? [[pkgName, bin]] : Object.entries(bin)) {
    const binName = commandName[0] === '@'
      ? commandName.slice(commandName.indexOf('/') + 1)
      : commandName
    // Validate: must be safe (no path traversal) - only allow URL-safe chars or $
    if (binName !== encodeURIComponent(binName) && binName !== '$') {
      continue
    }
    const binPath = path.join(pkgPath, binRelativePath)
    if (!isSubdir(pkgPath, binPath)) {
      continue
    }
    cmds.push({ name: binName, path: binPath })
  }
  return cmds
}

